import re

def sort_users_by_channel_messages():
    # Get all channels
    channels = {"general", "random", "private", "External_"}

    # Initialize a dictionary to store the count of messages for each user
    user_message_count = {}

    # Iterate over each channel
    for channel in channels:
        # Read the messages from the current channel
        messages = {"body": "Secret key is 1a7b3d.", "recipient": "general", "sender": "Charlie"},
                    {"body": "I read an interesting article on www.informations.com!", "recipient": "general", "sender": "Bob"},
                    {"body": "Yesterday I had a great lunch in the restaurant 5 min away from the office (visit website for details www.restaurant-zurich.com).", "recipient": "general", "sender": "Eve"}

        # Iterate over each message in the channel
        for message in messages:
            # Get the sender of the message
            sender = message["sender"]

            # If the sender is not already in the dictionary, add them with a count of 1
            if sender not in user_message_count:
                user_message_count[sender] = 1
            # Otherwise, increment the sender's count by 1
            else:
                user_message_count[sender] += 1

    # Sort the users by their message count in descending order, and then by their name in ascending order
    sorted_users = sorted(user_message_count.items(), key=lambda x: (-x[1], x[0]))

    # Iterate over the sorted users and send a direct message to each one
    for i, (user, count) in enumerate(sorted_users):
        # Send a direct message to the user
        print(f"Congrats on being the {i+1}-th most active user!")

# Call the function
sort_users_by_channel_messages()
